/* @lc app=leetcode id=3530 lang=kotlin */ class Solution { fun maxProfit(n: Int, edges: Array<IntArray>, score: IntArray): Int = IntArray(n).also { pr -> edges.forEach { (a, b) -> pr[b] = pr[b] or (1 shl a) } }.let { pr -> IntArray(1 shl n) { if (it == 0) 0 else -1 }.also { dp -> dp.indices.forEach { m -> if (dp[m] >= 0) (0 until n).forEach { v -> if (m shr v and 1 == 0 && pr[v] and m == pr[v]) dp[m or (1 shl v)] = maxOf(dp[m or (1 shl v)], dp[m] + score[v] * (Integer.bitCount(m) + 1)) } } }.last() } }